/**
 * End-to-end comparison with repro_eval's RpdEvaluator / RplEvaluator
 * (results generated by scripts/make_fixtures.py with the Python package).
 */
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { runExperiment } from '../src/core/experiment.ts';
import type { ExperimentResult, Pair } from '../src/core/experiment.ts';
import { MEASURES } from '../src/core/measures.ts';
import type { ScoreTable } from '../src/core/trec-eval.ts';
import { parseQrels, parseRun } from '../src/core/trec-format.ts';
import { assertRecordClose, fixtureJson, fixtureText, pytrecEvalRounding } from './helpers.ts';

type ByMeasure = Record<string, number>;
type ByTopic = Record<string, number>;
type BaseAdv<T> = { baseline: T; advanced: T };

interface RpdReference {
  trim: number;
  scores: Partial<Record<'orig_b' | 'orig_a' | 'rep_b' | 'rep_a', Record<string, ByMeasure>>>;
  arp: Record<'orig_b' | 'orig_a' | 'rep_b' | 'rep_a', ByMeasure>;
  ktu: BaseAdv<ByTopic>;
  ktu_mean: BaseAdv<number>;
  rbo: BaseAdv<ByTopic>;
  rbo_mean: BaseAdv<number>;
  rmse: BaseAdv<ByMeasure>;
  nrmse: BaseAdv<ByMeasure>;
  er: ByMeasure;
  dri: ByMeasure;
  ttest: BaseAdv<ByMeasure>;
}

interface Reference {
  versions: { machine?: string };
  results: {
    rpd_trim1000: RpdReference;
    rpd_trim25: RpdReference;
    rpd_identical: { ttest: BaseAdv<ByMeasure>; ktu_mean: BaseAdv<number>; rbo_mean: BaseAdv<number>; er: ByMeasure };
    rpl: { scores: Record<'rep_b' | 'rep_a', Record<string, ByMeasure>>; er: ByMeasure; dri: ByMeasure; ttest: BaseAdv<ByMeasure> };
  };
}

const fixture = fixtureJson<Reference>('repro.json');
const ref = fixture.results;
const iprecRounding = pytrecEvalRounding(fixture.versions);
const run = (name: string) => parseRun(fixtureText(`repro/${name}.txt`)).run;
const qrels = (name: string) => parseQrels(fixtureText(`repro/${name}.txt`)).qrels;

const byMeasure = (values: ArrayLike<number>): ByMeasure => Object.fromEntries(MEASURES.map((m, i) => [m.id, values[i] as number]));
const perTopic = (map: ReadonlyMap<string, number>): ByTopic => Object.fromEntries(map);
const scoresByTopic = (table: ScoreTable): Record<string, ByMeasure> =>
  Object.fromEntries(table.topics.map((topic, t) => [topic, byMeasure(table.values[t] as Float64Array)]));

function both<T>(pair: Pair<T> | undefined): BaseAdv<T> {
  assert.ok(pair?.advanced !== undefined, 'expected baseline and advanced results');
  return { baseline: pair.baseline, advanced: pair.advanced };
}

function rpd(runLength: number, repB = 'rpd_b', repA = 'rpd_a'): ExperimentResult {
  return runExperiment({
    mode: 'rpd',
    qrels: qrels('qrels_rpd'),
    original: { baseline: run('orig_b'), advanced: run('orig_a') },
    reproductions: [{ name: 'reproduction', runs: { baseline: run(repB), advanced: run(repA) } }],
    settings: { runLength, iprecRounding },
  });
}

function checkRpd(result: ExperimentResult, expected: RpdReference): void {
  const rep = result.reproductions[0];
  assert.ok(rep);
  const { scores } = expected;
  const tables = { orig_b: result.original.scores.baseline, orig_a: both(result.original.scores).advanced, rep_b: rep.scores.baseline, rep_a: both(rep.scores).advanced };
  for (const name of ['orig_b', 'orig_a', 'rep_b', 'rep_a'] as const) {
    const want = scores[name];
    if (want) {
      const got = scoresByTopic(tables[name]);
      assert.deepEqual(Object.keys(got).sort(), Object.keys(want).sort(), `${name}: topics`);
      for (const topic of Object.keys(want)) assertRecordClose(got[topic] as ByMeasure, want[topic] as ByMeasure, `${name} topic ${topic}`, 1e-13, 1e-13);
    }
  }
  const arps = { orig_b: result.original.arp.baseline, orig_a: both(result.original.arp).advanced, rep_b: rep.arp.baseline, rep_a: both(rep.arp).advanced };
  for (const name of ['orig_b', 'orig_a', 'rep_b', 'rep_a'] as const) assertRecordClose(byMeasure(arps[name]), expected.arp[name], `ARP ${name}`, 1e-14, 1e-13);

  const ktu = both(rep.ktu);
  const rbo = both(rep.rbo);
  for (const role of ['baseline', 'advanced'] as const) {
    assertRecordClose(perTopic(ktu[role].perTopic), expected.ktu[role], `KTU ${role}`, 1e-14, 0);
    assertRecordClose({ mean: ktu[role].mean }, { mean: expected.ktu_mean[role] }, `KTU mean ${role}`, 1e-15, 0);
    assertRecordClose(perTopic(rbo[role].perTopic), expected.rbo[role], `RBO ${role}`, 1e-15, 0);
    assertRecordClose({ mean: rbo[role].mean }, { mean: expected.rbo_mean[role] }, `RBO mean ${role}`, 1e-15, 0);
    assertRecordClose(byMeasure(both(rep.rmse)[role]), expected.rmse[role], `RMSE ${role}`, 1e-14, 1e-13);
    assertRecordClose(byMeasure(both(rep.nrmse)[role]), expected.nrmse[role], `nRMSE ${role}`, 1e-14, 1e-13);
    assertRecordClose(byMeasure(both(rep.ttest)[role].map((r) => r.pvalue)), expected.ttest[role], `p-values ${role}`, 1e-300, 1e-9);
  }
  assert.ok(rep.er && rep.dri);
  assertRecordClose(byMeasure(rep.er), expected.er, 'ER', 1e-13, 1e-11);
  assertRecordClose(byMeasure(rep.dri), expected.dri, 'ΔRI', 1e-13, 1e-11);
}

describe('repro_eval parity', () => {
  test('reproducibility, runs trimmed to 1000', () => {
    const expected = ref.rpd_trim1000;
    assert.equal(expected.trim, 1000);
    checkRpd(rpd(1000), expected);
  });

  test('reproducibility, runs trimmed to 25', () => {
    checkRpd(rpd(25), ref.rpd_trim25);
  });

  test('identical runs: KTU = RBO = ER = 1 and all p-values are 1', () => {
    const result = rpd(1000, 'orig_b', 'orig_a');
    const rep = result.reproductions[0];
    assert.ok(rep);
    const expected = ref.rpd_identical;
    for (const role of ['baseline', 'advanced'] as const) {
      assertRecordClose(byMeasure(both(rep.ttest)[role].map((r) => r.pvalue)), expected.ttest[role], `p-values ${role}`);
      assert.equal(both(rep.ktu)[role].mean, expected.ktu_mean[role]);
      assert.equal(both(rep.rbo)[role].mean, expected.rbo_mean[role]);
    }
    assert.ok(rep.er);
    assertRecordClose(byMeasure(rep.er), expected.er, 'ER');
  });

  test('replicability', () => {
    const result = runExperiment({
      mode: 'rpl',
      qrels: qrels('qrels_rpd'),
      replicationQrels: qrels('qrels_rpl'),
      original: { baseline: run('orig_b'), advanced: run('orig_a') },
      reproductions: [{ name: 'replication', runs: { baseline: run('rpl_b'), advanced: run('rpl_a') } }],
      settings: { iprecRounding },
    });
    const rep = result.reproductions[0];
    assert.ok(rep);
    const expected = ref.rpl;
    const tables = { rep_b: rep.scores.baseline, rep_a: both(rep.scores).advanced };
    for (const name of ['rep_b', 'rep_a'] as const) {
      const got = scoresByTopic(tables[name]);
      for (const topic of Object.keys(expected.scores[name])) {
        assertRecordClose(got[topic] as ByMeasure, expected.scores[name][topic] as ByMeasure, `${name} topic ${topic}`, 1e-13, 1e-13);
      }
    }
    assert.ok(rep.er && rep.dri);
    assertRecordClose(byMeasure(rep.er), expected.er, 'ER', 1e-13, 1e-11);
    assertRecordClose(byMeasure(rep.dri), expected.dri, 'ΔRI', 1e-13, 1e-11);
    for (const role of ['baseline', 'advanced'] as const) {
      assertRecordClose(byMeasure(both(rep.ttest)[role].map((r) => r.pvalue)), expected.ttest[role], `p-values ${role}`, 1e-300, 1e-9);
    }
    assert.equal(rep.ktu, undefined);
    assert.equal(rep.rmse, undefined);
  });
});
